import pytest
from src.rpn import evaluate_rpn


def test_single_number():
    assert evaluate_rpn(["42"]) == 42.0


def test_simple_addition():
    assert evaluate_rpn(["3", "4", "+"]) == 7.0


def test_multiplication_and_addition():
    # 2 3 * 4 + = (2*3)+4 = 10
    assert evaluate_rpn(["2", "3", "*", "4", "+"]) == 10.0


def test_subtraction():
    assert evaluate_rpn(["10", "3", "-"]) == 7.0


def test_division():
    assert evaluate_rpn(["10", "2", "/"]) == 5.0


def test_complex_expression():
    # 5 1 2 + 4 * + 3 - = 5 + (1+2)*4 - 3 = 5 + 12 - 3 = 14
    result = evaluate_rpn(["5", "1", "2", "+", "4", "*", "+", "3", "-"])
    assert abs(result - 14.0) < 1e-9


def test_invalid_expression_raises():
    with pytest.raises((ValueError, IndexError)):
        evaluate_rpn(["+"])  # no operands
